int pair_sum_exists(const std::vector<long long>& a, long long target) {
    long long left = 0, right = (long long)a.size() - 1;
    while (left < right) {
        long long s = a[left] + a[right];
        if (s == target) return 1;
        if (s < target) left++;
        else right--;
    }
    return 0;
}

