long long max_window_sum(const std::vector<long long>& a, long long k) {
    long long n = (long long)a.size();
    if (k < 1) k = 1;
    if (k > n) k = n;
    long long sum = 0;
    for (long long i = 0; i < k; i++) sum += a[i];
    long long best = sum;
    for (long long i = k; i < n; i++) {
        sum += a[i] - a[i - k];
        if (sum > best) best = sum;
    }
    return best;
}

