long long closest_pair_sum(const std::vector<long long>& a, long long target) {
    long long left = 0, right = (long long)a.size() - 1;
    long long best = -1;
    bool seen = false;
    while (left < right) {
        long long s = a[left] + a[right];
        long long d = s - target;
        if (d < 0) d = -d;
        if (!seen || d < best) {
            best = d;
            seen = true;
        }
        if (s < target) left++;
        else right--;
    }
    return best;
}

