std::vector<long long> running_max(const std::vector<long long>& a) {
    std::vector<long long> out(a.size());
    long long best = 0;
    bool first = true;
    for (size_t i = 0; i < a.size(); i++) {
        if (first || a[i] > best) best = a[i];
        first = false;
        out[i] = best;
    }
    return out;
}

