int cross_match(const std::vector<long long>& a, const std::vector<long long>& b, long long target) {
    long long i = 0, j = (long long)b.size() - 1;
    while (i < (long long)a.size() && j >= 0) {
        long long s = a[i] + b[j];
        if (s == target) return 1;
        if (s < target) i++;
        else j--;
    }
    return 0;
}

