int balance_index(const std::vector<long long>& a) {
    long long total = 0;
    for (long long v : a) total += v;
    long long leftSum = 0;
    for (size_t i = 0; i < a.size(); i++) {
        if (leftSum == total - leftSum - a[i]) return (int)i;
        leftSum += a[i];
    }
    return -1;
}

