long long count_target_pairs(const std::vector<long long>& a, long long target) {
    long long left = 0, right = (long long)a.size() - 1;
    long long pairs = 0;
    while (left < right) {
        long long s = a[left] + a[right];
        if (s < target) left++;
        else if (s > target) right--;
        else {
            if (a[left] == a[right]) {
                long long cnt = right - left + 1;
                pairs += cnt * (cnt - 1) / 2;
                break;
            }
            long long cl = 1;
            while (left + 1 < right && a[left] == a[left + 1]) { left++; cl++; }
            long long cr = 1;
            while (right - 1 > left && a[right] == a[right - 1]) { right--; cr++; }
            pairs += cl * cr;
            left++;
            right--;
        }
    }
    return pairs;
}

