void zeros_to_back(std::vector<long long>& a) {
    long long last = 0;
    for (size_t i = 0; i < a.size(); i++) {
        if (a[i] != 0) {
            a[last] = a[i];
            last++;
        }
    }
    for (size_t i = last; i < a.size(); i++) a[i] = 0;
}

