long long max_price_gap(const std::vector<long long>& prices) {
    long long minSoFar = prices[0];
    long long best = -1;
    for (size_t i = 1; i < prices.size(); i++) {
        long long profit = prices[i] - minSoFar;
        if (profit > 0 && profit > best) best = profit;
        if (prices[i] < minSoFar) minSoFar = prices[i];
    }
    return best;
}

