void dutch_flag(std::vector<int>& balls) {
    int low = 0, mid = 0;
    int high = (int)balls.size() - 1;
    while (mid <= high) {
        if (balls[mid] == 0) {
            int tmp = balls[low];
            balls[low] = balls[mid];
            balls[mid] = tmp;
            low++;
            mid++;
        } else if (balls[mid] == 1) {
            mid++;
        } else {
            int tmp = balls[mid];
            balls[mid] = balls[high];
            balls[high] = tmp;
            high--;
        }
    }
}

