long long dominant_vote(const std::vector<long long>& votes) {
    long long candidate = 0;
    long long strength = 0;
    for (long long v : votes) {
        if (strength == 0) candidate = v;
        if (v == candidate) strength++;
        else strength--;
    }
    long long occur = 0;
    for (long long v : votes) {
        if (v == candidate) occur++;
    }
    if (occur > (long long)votes.size() / 2) return candidate;
    return -1;
}

int main() {
    long long n;
    std::cin >> n;
    std::vector<long long> votes(n);
    for (long long i = 0; i < n; i++) std::cin >> votes[i];
    std::cout << dominant_vote(votes) << "\n";
    return 0;
}
